import json, sys
from pathlib import Path

HOME = Path.home()
alvos = json.loads(Path('/mnt/dados/harness/autofagia/alvos.json').read_text())
agents_dir = HOME / '.config' / 'opencode' / 'agents'

try:
    import yaml
    def parse(txt):
        parts = txt.split('---', 2)
        return yaml.safe_load(parts[1]), parts[2]
except ImportError:
    def parse(txt):
        parts = txt.split('---', 2)
        fm = {}
        for line in parts[1].strip().splitlines():
            if not line or line.startswith(' ') or line.startswith('\t'):
                continue
            if ':' in line:
                k, v = line.split(':', 1)
                fm[k.strip()] = v.strip()
        return fm, parts[2]

ok = True
for a in alvos:
    slug = a['slug']
    p = agents_dir / f'{slug}.md'
    raw = p.read_text()
    fm, body = parse(raw)
    errs = []
    if fm.get('mode') != 'subagent':
        errs.append(f"mode={fm.get('mode')!r}")
    if 'origin' in fm:
        errs.append('origin present')
    if 'tags' in fm:
        errs.append('tags present')
    t = fm.get('tools')
    if not isinstance(t, dict) or not all(isinstance(v, bool) for v in t.values()):
        errs.append(f"tools not bool-map: {t!r}")
    if 'description: >-' in raw:
        errs.append('folded description scalar')
    if not isinstance(fm.get('description'), str) or '\n' in str(fm.get('description')):
        errs.append('description not single-line')
    if '## Origem' not in body:
        errs.append('no Origem section in body')
    if errs:
        ok = False
        print(f"FAIL {slug}: {errs}")
    else:
        print(f"OK   {slug}: mode={fm['mode']}, tools={list(t.keys())}, desc1line, Origem=yes")
print('ALL OK' if ok else 'FAILURES PRESENT')
sys.exit(0 if ok else 1)
EOF
